import pytest
from fastapi.testclient import TestClient
from backend.routers import orders

def test_create_order(client: TestClient, sample_order_payload: dict, clean_store):
    resp = client.post("/orders/", json=sample_order_payload)
    assert resp.status_code == 201
    data = resp.json()
    assert data["customer_id"] == sample_order_payload["customer_id"]
    assert data["status"] == "pending"
    assert "id" in data
    assert "created_at" in data

def test_get_order_not_found(client: TestClient):
    resp = client.get("/orders/nonexistent-id")
    assert resp.status_code == 404

def test_list_orders_pagination(client: TestClient, clean_store):
    for i in range(5):
        client.post("/orders/", json={
            "customer_id": f"u_{i}",
            "items": [],
            "total_amount": 10.0
        })
    resp = client.get("/orders/?limit=2&offset=0")
    assert resp.status_code == 200
    assert len(resp.json()) == 2

def test_update_status_invalid(client: TestClient, clean_store, sample_order_payload):
    create_resp = client.post("/orders/", json=sample_order_payload)
    order_id = create_resp.json()["id"]
    resp = client.put(f"/orders/{order_id}/status", params={"status": "invalid"})
    assert resp.status_code == 422

